import java.util.concurrent.ArrayBlockingQueue

// the blocking bounded channel (the common Scala answer for a work queue):
val q = new ArrayBlockingQueue[Job](256)
q.put(job)                 // blocks when full -> backpressure
val j = q.take()            // blocks when empty

// the typed, effectful channel with an explicit close (cats-effect):
import cats.effect.{Queue, IO}
def run(q: Queue[IO, Job]): IO[Unit] =
  q.take.flatMap(job => q.offer(job) *> IO.println(job.title)) *> q.take *> IO.unit
// Queue[bounded] blocks the offer when full (backpressure) and close() ends the stream.
// scala.concurrent.channels.Channel is unbounded and carries AnyRef (untyped)
// and has no close - termination is a poison pill or a shutdown message.
